/* steel-toggle v1.0.0 — vendor build for vasu-yadav-portfolio.
 * Self-contained ES module (no imports). Controlled mode: the page owns
 * theme state (localStorage + html classes); this element reflects
 * `checked` / aria-checked and fires `change` with target.checked.
 * Sound + renderer adapted from github.com/kvvasu/steel-toggle (MIT). */

const SOUND_PROFILES = {
  weighted: { duration: 0.075, body: 550, decay: 90, weight: 0.12, snap: 0.62, rebound: 0.012 },
  crisp: { duration: 0.065, body: 650, decay: 100, weight: 0.08, snap: 0.62, rebound: 0.007 },
  heavy: { duration: 0.13, body: 185, decay: 42, weight: 0.34, snap: 0.52, rebound: 0.014 },
  damped: { duration: 0.085, body: 135, decay: 68, weight: 0.26, snap: 0.25, rebound: 0.009 },
  chunky: { duration: 0.16, body: 110, decay: 34, weight: 0.43, snap: 0.43, rebound: 0.021 },
  metallic: { duration: 0.19, body: 920, decay: 30, weight: 0.2, snap: 0.56, rebound: 0.011 },
  relay: { duration: 0.09, body: 390, decay: 76, weight: 0.18, snap: 0.7, rebound: 0.025 },
  latch: { duration: 0.14, body: 235, decay: 48, weight: 0.32, snap: 0.4, rebound: 0.032 },
};

const LIGHT_ART = new URL("./steel-toggle-light.png", import.meta.url).href;
const DARK_ART = new URL("./steel-toggle-dark.png", import.meta.url).href;

const VERT = "attribute vec2 a;void main(){gl_Position=vec4(a,0.,1.);}";

const FRAG = `precision mediump float;
uniform vec2 uRes;uniform float uKnobX;
float sdRoundBox(vec2 p,vec2 b,float r){vec2 q=abs(p)-b+r;return length(max(q,0.))+min(max(q.x,q.y),0.)-r;}
float sdCircle(vec2 p,float r){return length(p)-r;}
float sdSegment(vec2 p,vec2 a,vec2 b){vec2 pa=p-a,ba=b-a;float h=clamp(dot(pa,ba)/dot(ba,ba),0.,1.);return length(pa-ba*h);}
void main(){
  vec2 uv=vec2(gl_FragCoord.x,uRes.y-gl_FragCoord.y);vec2 c=uRes*0.5;float cy=c.y;vec4 outCol=vec4(0.0);
  float dTrack=sdRoundBox(uv-c,c-vec2(1.0),5.0);float g=uv.y/uRes.y;
  vec3 metal=mix(vec3(0.902),vec3(0.741),smoothstep(0.0,1.0,g));
  metal=mix(metal,vec3(0.788),smoothstep(0.35,0.6,g)*0.55);
  float inside=1.0-smoothstep(-0.5,0.5,dTrack);
  vec3 col=mix(vec3(0.0),metal,inside);
  float border=smoothstep(-1.6,-0.6,dTrack)*(1.0-smoothstep(0.6,1.6,dTrack));
  col=mix(col,vec3(0.616),border);
  col+=vec3(0.9)*inside*(1.0-smoothstep(0.5,1.8,uv.y))*0.9;
  col*=1.0-inside*smoothstep(3.0,0.0,uRes.y-uv.y)*0.15;
  outCol=vec4(col,inside>0.0?1.0:0.0);
  vec2 l1=vec2(14.0,cy-5.0),l2=vec2(9.0,cy),l3=vec2(14.0,cy+5.0);
  vec2 r1=vec2(uRes.x-14.0,cy-5.0),r2=vec2(uRes.x-9.0,cy),r3=vec2(uRes.x-14.0,cy+5.0);
  float chev=min(min(sdSegment(uv,l1,l2),sdSegment(uv,l2,l3)),min(sdSegment(uv,r1,r2),sdSegment(uv,r2,r3)));
  float sh=1.0-smoothstep(0.6,1.6,chev+1.0);
  outCol.rgb=mix(outCol.rgb,vec3(1.0),sh*inside*0.85);
  float ink=1.0-smoothstep(0.6,1.6,chev);
  outCol.rgb=mix(outCol.rgb,vec3(0.373),ink*inside);
  float margin=7.0,r=13.0;float kx=mix(margin+r,uRes.x-margin-r,uKnobX);
  vec2 kp=uv-vec2(kx,cy);float dK=sdCircle(kp,r);
  float kIn=1.0-smoothstep(-0.5,0.5,dK);
  vec2 gp=kp-vec2(-4.0,-5.0);float shade=clamp(length(gp)/(r*1.6),0.0,1.0);
  vec3 knob=mix(vec3(0.353),vec3(0.098),shade);
  knob+=vec3(0.16)*(1.0-smoothstep(0.0,r*0.55,length(gp)));
  outCol.rgb=mix(outCol.rgb,knob,kIn);
  float ring=(1.0-smoothstep(0.4,1.2,abs(dK-6.0)))*kIn;
  outCol.rgb=mix(outCol.rgb,vec3(1.0),ring*0.14);
  gl_FragColor=vec4(outCol.rgb*outCol.a,outCol.a);
}`;

let audioCtx;

function playToggleSound(name = "weighted", toDark = false) {
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  try {
    audioCtx ??= new AC();
    if (audioCtx.state === "suspended") audioCtx.resume();
    const p = SOUND_PROFILES[name] || SOUND_PROFILES.weighted;
    const sr = audioCtx.sampleRate;
    const buf = audioCtx.createBuffer(1, Math.ceil(sr * p.duration), sr);
    const d = buf.getChannelData(0);
    let seed = 1947;
    const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0), seed / 2147483648 - 1);
    const pitch = toDark ? 0.96 : 1.04;
    for (let i = 0; i < d.length; i++) {
      const u = i / sr, f = rnd();
      const snap = p.snap * f * Math.exp(-u * 510);
      const rebound = u < p.rebound ? 0 : f * 0.24 * Math.exp(-(u - p.rebound) * 330);
      const body = p.weight * Math.exp(-u * p.decay) *
        (Math.sin(2 * Math.PI * p.body * pitch * u) * 0.62 +
         Math.sin(2 * Math.PI * p.body * 2.73 * u) * 0.24 +
         Math.sin(2 * Math.PI * p.body * 6.31 * u) * 0.14);
      const rumble = f * 0.1 * Math.exp(-u * 95);
      d[i] = Math.tanh((snap + rebound + body + rumble) * 1.3) * 0.65 *
             Math.min(u / 4e-4, 1) * Math.min((p.duration - u) / 0.005, 1);
    }
    const src = audioCtx.createBufferSource();
    src.buffer = buf;
    src.connect(audioCtx.destination);
    src.start();
  } catch { /* audio is best-effort */ }
}

class SteelToggle extends HTMLElement {
  static observedAttributes = ["checked", "muted"];

  #button = null;
  #canvas = null;
  #gl = null;
  #anim = 0;
  #ro = null;

  connectedCallback() {
    if (this.shadowRoot) return;
    const root = this.attachShadow({ mode: "open" });
    root.innerHTML = `
      <style>
        :host { display: inline-flex; min-width: 44px; min-height: 44px; align-items: center; justify-content: center; --focus: currentColor; }
        button {
          appearance: none; display: block; width: 84px; height: 44px; padding: 0; border: 0;
          border-radius: 5px; background: transparent; cursor: pointer; position: relative;
          touch-action: manipulation; -webkit-tap-highlight-color: transparent;
        }
        button::before { content: ""; position: absolute; inset: -2px 0; }
        button:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
        canvas { visibility: hidden; display: block; width: 100%; height: 100%; pointer-events: none; }
        .fallback { position: absolute; inset: 0; background: url("${LIGHT_ART}") center / 100% 100% no-repeat; }
        button[aria-checked="true"] .fallback { background-image: url("${DARK_ART}"); }
        :host([data-renderer="webgl"]) canvas { visibility: visible; }
        :host([data-renderer="webgl"]) .fallback { visibility: hidden; }
        @media (prefers-reduced-motion: reduce) {
          canvas { display: none; }
          .fallback { visibility: visible !important; }
        }
      </style>
      <button type="button" role="switch" aria-label="Toggle dark mode" aria-checked="false" title="Toggle dark mode">
        <canvas aria-hidden="true"></canvas>
        <span class="fallback" aria-hidden="true"></span>
      </button>`;
    this.#button = root.querySelector("button");
    this.#canvas = root.querySelector("canvas");

    this.#sync();
    this.#initRenderer();

    this.#button.addEventListener("click", () => {
      this.checked = !this.checked;
      this.dispatchEvent(new Event("change", { bubbles: true }));
      if (!this.hasAttribute("muted") && document.documentElement.getAttribute("data-sound") !== "muted") {
        playToggleSound(this.getAttribute("sound") || "weighted", this.checked);
      }
    });
    this.#button.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
        e.preventDefault();
        const wantChecked = e.key === "ArrowRight";
        if (wantChecked !== this.checked) {
          this.checked = wantChecked;
          this.dispatchEvent(new Event("change", { bubbles: true }));
          if (!this.hasAttribute("muted") && document.documentElement.getAttribute("data-sound") !== "muted") {
            playToggleSound(this.getAttribute("sound") || "weighted", this.checked);
          }
        }
      }
    });

    this.#ro = new ResizeObserver(() => this.#resizeCanvas());
    this.#ro.observe(this);
  }

  disconnectedCallback() {
    this.#ro?.disconnect();
  }

  attributeChangedCallback() {
    this.#sync();
    if (this.#gl) this.#render();
  }

  get checked() {
    return this.hasAttribute("checked");
  }

  set checked(v) {
    this.toggleAttribute("checked", Boolean(v));
  }

  #sync() {
    const on = this.checked;
    this.toggleAttribute("data-dark", on);
    if (this.#button) {
      this.#button.setAttribute("aria-checked", String(on));
      this.#button.title = on ? "Switch to light mode" : "Switch to dark mode";
    }
  }

  #initRenderer() {
    if (this.#gl || !this.#canvas) return;
    if (this.getAttribute("nowebgl") === "1" || window.STEEL_TOGGLE_NOWEBGL === 1) return;
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) return;
    try {
      const gl = this.#canvas.getContext("webgl", { alpha: true, premultipliedAlpha: true, antialias: true });
      if (!gl) return;
      const compile = (type, src) => {
        const sh = gl.createShader(type);
        gl.shaderSource(sh, src);
        gl.compileShader(sh);
        if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh) || "compile failed");
        return sh;
      };
      const prog = gl.createProgram();
      gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
      gl.linkProgram(prog);
      if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog) || "link failed");
      gl.useProgram(prog);
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
      const loc = gl.getAttribLocation(prog, "a");
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
      this.#gl = { gl, uRes: gl.getUniformLocation(prog, "uRes"), uKnobX: gl.getUniformLocation(prog, "uKnobX") };
      this.setAttribute("data-renderer", "webgl");
      this.#resizeCanvas();
    } catch {
      if (this.#gl) {
        this.#gl.gl.getExtension("WEBGL_lose_context")?.loseContext();
        this.#gl = null;
      }
      this.removeAttribute("data-renderer");
    }
  }

  #resizeCanvas() {
    if (!this.#gl) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(84 * dpr));
    const h = Math.max(1, Math.round(44 * dpr));
    if (this.#canvas.width !== w || this.#canvas.height !== h) {
      this.#canvas.width = w;
      this.#canvas.height = h;
    }
    this.#render(true);
  }

  #draw(knobX) {
    if (!this.#gl) return;
    const { gl, uRes, uKnobX } = this.#gl;
    gl.viewport(0, 0, this.#canvas.width, this.#canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(uRes, this.#canvas.width, this.#canvas.height);
    gl.uniform1f(uKnobX, knobX);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }

  #render(instant = false) {
    if (!this.#gl) return;
    const target = this.checked ? 1 : 0;
    cancelAnimationFrame(this.#anim);
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    if (instant || reduced) {
      this.#draw(target);
      return;
    }
    const start = performance.now();
    const from = Number(this.#canvas.dataset.kx || (this.checked ? 0 : 1));
    const DUR = 220;
    const ease = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
    const step = (now) => {
      const t = Math.min(1, (now - start) / DUR);
      const kx = from + (target - from) * ease(t);
      this.#canvas.dataset.kx = String(kx);
      this.#draw(kx);
      if (t < 1) this.#anim = requestAnimationFrame(step);
    };
    this.#anim = requestAnimationFrame(step);
  }
}

if (typeof customElements !== "undefined" && !customElements.get("steel-toggle")) {
  customElements.define("steel-toggle", SteelToggle);
}
